<script setup lang="ts">
const api=useApi(); const { data: reports }=await useAsyncData('admin-reports',()=>api.request<any[]>('/admin/reports').catch(()=>[]))
const q=ref(''); const filtered=computed(()=> (reports.value||[]).filter(r=>!q.value||`${r.ref} ${r.summary} ${r.risk}`.toLowerCase().includes(q.value.toLowerCase())))
</script>
<template><div><div class="mb-5 flex flex-col gap-3 md:flex-row md:items-end md:justify-between"><div><p class="label-mono text-signal-deep">Diagnostics</p><h1 class="mt-1 font-display text-[clamp(2.2rem,3vw,2.7rem)] font-semibold tracking-[-.045em]">Inspection reports.</h1><p class="mt-1 text-[11.5px] text-ink/45">Screening outcomes and customer deliverables.</p></div><input v-model="q" class="a-input md:w-64" placeholder="Search report"></div><div class="grid gap-3 lg:grid-cols-2"><div v-for="r in filtered" :key="r._id" class="a-card p-4"><div class="flex items-start justify-between"><div><p class="font-mono text-[9px]">{{ r.ref }}</p><p class="mt-1 font-display text-[20px]">{{ (r.maxDepthPct||0).toFixed(1) }}% deepest loss</p></div><StatusPill :status="r.risk"/></div><p class="mt-2 line-clamp-2 text-[11px] leading-relaxed text-ink/50">{{ r.summary }}</p><div class="mt-3 grid grid-cols-3 gap-2 border-t border-ink/10 pt-3"><div><p class="font-mono text-[7px] uppercase text-ink/30">CGR</p><p class="text-[12px]">{{ r.cgr }} mm/y</p></div><div><p class="font-mono text-[7px] uppercase text-ink/30">Life</p><p class="text-[12px]">{{ r.remainingLifeYears }} y</p></div><div><p class="font-mono text-[7px] uppercase text-ink/30">Anomalies</p><p class="text-[12px]">{{ r.anomalies?.length }}</p></div></div></div></div></div></template>
